const CHART_CSS = `
.etdc-card{ background:#ffffff; border:1px solid #ECEEF2; border-radius:18px; padding:14px 10px 10px; }
.etdc-scroll{ overflow-x:auto; -webkit-overflow-scrolling:touch; scrollbar-width:thin; border-radius:12px; }
.etdc-inner{ min-width:880px; }
.etdc-wrap{ position:relative; width:100%; }
.etdc-wrap svg{ display:block; width:100%; height:auto; }
.etdc-ovl{ position:absolute; inset:0; width:100%; height:100%; pointer-events:none; }
.etdc-xhair{ stroke:#C9CFDB; stroke-width:1; stroke-dasharray:4 4; display:none; }
.etdc-marker{ display:none; }
.etdc-tip{ position:absolute; pointer-events:none; z-index:5; background:#ffffff; border:1px solid #E3E7EE; border-radius:12px; box-shadow:0 10px 28px rgba(16,24,40,0.12); padding:12px 14px; min-width:216px; display:none; font-size:13px; color:#3A4356; }
.etdc-tip-date{ font-weight:700; font-size:13px; color:#1B2230; margin-bottom:8px; white-space:nowrap; }
.etdc-tip-row{ display:flex; align-items:center; gap:8px; padding:2.5px 0; white-space:nowrap; }
.etdc-tip-dot{ width:9px; height:9px; border-radius:50%; flex:0 0 9px; }
.etdc-tip-name{ flex:1; }
.etdc-tip-val{ font-weight:600; color:#1B2230; font-variant-numeric:tabular-nums; }
`;

export const DeliveryChart: React.FC = () => {
  const wrapRef = useRef<HTMLDivElement>(null);
  const tipRef = useRef<HTMLDivElement>(null);
  const dateRef = useRef<HTMLDivElement>(null);
  const xhairRef = useRef<SVGLineElement>(null);
  const markerRefs = useRef<Record<SeriesKey, SVGCircleElement | null>>({ max: null, mean: null, min: null });
  const valRefs = useRef<Record<SeriesKey, HTMLSpanElement | null>>({ max: null, mean: null, min: null });
  const scrollRef = useRef<HTMLDivElement>(null);
  const manualUntilRef = useRef(0);

  useEffect(() => {
    const wrap = wrapRef.current;
    const tip = tipRef.current;
    const xhair = xhairRef.current;
    if (!wrap || !tip || !xhair) return;

    const hide = () => {
      tip.style.display = 'none';
      xhair.style.display = 'none';
      SERIES.forEach(n => {
        const m = markerRefs.current[n];
        if (m) m.style.display = 'none';
      });
    };

    const onMove = (clientX: number, clientY: number) => {
      const rect = wrap.getBoundingClientRect();
      const sx = ((clientX - rect.left) / rect.width) * 1600;
      if (sx < 90 || sx > 1560) { hide(); return; }

      let i = Math.round(((sx - 90) / 1470) * (RAW.length - 1));
      i = Math.max(0, Math.min(RAW.length - 1, i));
      const row = RAW[i];

      xhair.setAttribute('x1', String(row.x));
      xhair.setAttribute('x2', String(row.x));
      xhair.style.display = 'block';
      if (dateRef.current) dateRef.current.textContent = row.date;

      const dd = DENSE.max;
      let di = Math.round(((sx - 90) / 1470) * (dd.length - 1));
      di = Math.max(0, Math.min(dd.length - 1, di));

      SERIES.forEach(n => {
        const p = DENSE[n][di];
        const m = markerRefs.current[n];
        if (m) {
          m.setAttribute('cx', String(p[0]));
          m.setAttribute('cy', String(p[1]));
          m.style.display = 'block';
        }
        const v = valRefs.current[n];
        if (v) v.textContent = row.vals[n];
      });

      tip.style.display = 'block';
      const tx = (row.x / 1600) * rect.width;
      let left = tx + 18;
      const tw = tip.offsetWidth;
      if (left + tw > rect.width - 6) left = tx - tw - 18;
      let top = clientY - rect.top - 40;
      if (top < 0) top = 8;
      tip.style.left = left + 'px';
      tip.style.top = top + 'px';
    };

    const onMouseMove = (e: MouseEvent) => onMove(e.clientX, e.clientY);
    const onTouchStart = (e: TouchEvent) => { if (e.touches[0]) onMove(e.touches[0].clientX, e.touches[0].clientY); };
    const onTouchMove = (e: TouchEvent) => { if (e.touches[0]) onMove(e.touches[0].clientX, e.touches[0].clientY); };
    const onTouchEnd = () => { window.setTimeout(hide, 1200); };

    wrap.addEventListener('mousemove', onMouseMove);
    wrap.addEventListener('mouseleave', hide);
    wrap.addEventListener('touchstart', onTouchStart, { passive: true });
    wrap.addEventListener('touchmove', onTouchMove, { passive: true });
    wrap.addEventListener('touchend', onTouchEnd);

    return () => {
      wrap.removeEventListener('mousemove', onMouseMove);
      wrap.removeEventListener('mouseleave', hide);
      wrap.removeEventListener('touchstart', onTouchStart);
      wrap.removeEventListener('touchmove', onTouchMove);
      wrap.removeEventListener('touchend', onTouchEnd);
    };
  }, []);

  // Scrub-эффект: пока карточка графика видна целиком, её горизонтальная
  // прокрутка привязана к вертикальной прокрутке страницы (вниз — график
  // едет слева направо, вверх — обратно). При ручном взаимодействии с
  // графиком автопрокрутка уступает на ~1,6 с.
  useEffect(() => {
    const scrollEl = scrollRef.current;
    if (!scrollEl) return;
    const card = scrollEl.closest('.etdc-card') as HTMLElement | null;
    if (!card) return;

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    let raf = 0;
    let touchX = 0;
    let touchY = 0;

    const pause = () => {
      manualUntilRef.current = Date.now() + 1600;
    };

    const update = () => {
      raf = 0;
      const vh = window.innerHeight;
      const rect = card.getBoundingClientRect();
      const cardH = rect.height;
      const maxScroll = Math.max(0, scrollEl.scrollWidth - scrollEl.clientWidth);
      if (cardH >= vh - 8 || maxScroll <= 0) return;
      const scrollY = window.scrollY;
      const startScroll = rect.bottom + scrollY - vh;
      const endScroll = rect.top + scrollY;
      const winLen = endScroll - startScroll;
      if (winLen <= 0) return;
      const progress = Math.max(0, Math.min(1, (scrollY - startScroll) / winLen));
      if (Date.now() > manualUntilRef.current) {
        scrollEl.scrollLeft = progress * maxScroll;
      }
    };

    const onScroll = () => {
      if (!raf) raf = window.requestAnimationFrame(update);
    };

    const onWheel = (e: WheelEvent) => {
      if (Math.abs(e.deltaX) > Math.abs(e.deltaY) || e.shiftKey) pause();
    };

    const onTouchStart = (e: TouchEvent) => {
      const t = e.touches[0];
      if (t) {
        touchX = t.clientX;
        touchY = t.clientY;
      }
    };

    const onTouchMove = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t) return;
      const dx = t.clientX - touchX;
      const dy = t.clientY - touchY;
      if (Math.abs(dx) > 12 && Math.abs(dx) > Math.abs(dy) * 1.2) pause();
    };

    const onMouseDown = () => pause();

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    scrollEl.addEventListener('wheel', onWheel, { passive: true });
    scrollEl.addEventListener('touchstart', onTouchStart, { passive: true });
    scrollEl.addEventListener('touchmove', onTouchMove, { passive: true });
    scrollEl.addEventListener('mousedown', onMouseDown);

    update();

    return () => {
      if (raf) window.cancelAnimationFrame(raf);
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      scrollEl.removeEventListener('wheel', onWheel);
      scrollEl.removeEventListener('touchstart', onTouchStart);
      scrollEl.removeEventListener('touchmove', onTouchMove);
      scrollEl.removeEventListener('mousedown', onMouseDown);
    };
  }, []);

  return (
    <div className="etdc-card">
      <style>{CHART_CSS}</style>
      <div className="etdc-scroll" ref={scrollRef}>
        <div className="etdc-inner">
          <div className="etdc-wrap" ref={wrapRef}>
            <div dangerouslySetInnerHTML={{ __html: STATIC_SVG }} />
            <svg viewBox="0 0 1600 900" className="etdc-ovl" aria-hidden="true">
              <line ref={xhairRef} className="etdc-xhair" x1={0} y1={150} x2={0} y2={805} />
              <circle ref={el => { markerRefs.current.max = el; }} className="etdc-marker" r={5.5} fill="#D2663A" stroke="#ffffff" strokeWidth={2} />
              <circle ref={el => { markerRefs.current.mean = el; }} className="etdc-marker" r={5.5} fill="#4F5E8C" stroke="#ffffff" strokeWidth={2} />
              <circle ref={el => { markerRefs.current.min = el; }} className="etdc-marker" r={5.5} fill="#74A5D8" stroke="#ffffff" strokeWidth={2} />
            </svg>
            <div className="etdc-tip" ref={tipRef}>
              <div className="etdc-tip-date" ref={dateRef} />
              {SERIES.map(n => (
                <div key={n} className="etdc-tip-row">
                  <span className="etdc-tip-dot" style={{ background: COLORS[n] }} />
                  <span className="etdc-tip-name">{LABELS[n]}</span>
                  <span className="etdc-tip-val" ref={el => { valRefs.current[n] = el; }} />
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
